@app.post("/v1/cases")
def create_case(case: CaseIn):
    cid = next_id
    cases[cid] = case.model_dump()
    return {"case_id": cid, **cases[cid]}

@app.put("/v1/cases/{case_id}")
def replace_case(case_id: int, case: CasePatch):
    row = cases[case_id]
    row.update(case.model_dump(exclude_none=True))
    return row

# CasePatch: title and priority are both optional
